mapper.select:
SELECT *
FROM em_prediction_batch

    AND project_id = #{query.projectId}
    AND batch_code = #{query.batchCode}
    AND id = #{query.batchId}
    AND status = #{query.status}

ORDER BY base_time DESC, id DESC
LIMIT #{limit}

SELECT *
FROM em_prediction_model

    AND project_id = #{query.projectId}
    AND model_code = #{query.modelCode}
    AND target_type = #{query.targetType}
    AND status = 'active'

ORDER BY model_code ASC, model_version DESC, id DESC
LIMIT #{limit}

SELECT *
FROM em_prediction_feature_mapping

    AND project_id = #{query.projectId}
    AND target_type = #{query.targetType}
    AND feature_code = #{query.featureCode}
    AND enabled = 1

ORDER BY target_type ASC, feature_order ASC, id ASC
LIMIT #{limit}

SELECT d.*, r.result_hash AS run_result_hash, b.output_hash AS batch_output_hash
FROM em_prediction_display d
LEFT JOIN em_prediction_run r ON r.id = d.run_id
LEFT JOIN em_prediction_batch b ON b.id = d.batch_id

    AND d.project_id = #{query.projectId}
    AND d.batch_id = #{query.batchId}
    AND d.batch_code = #{query.batchCode}
    AND d.run_id = #{query.runId}
    AND d.model_code = #{query.modelCode}
    AND d.target_type = #{query.targetType}
    AND d.feature_code = #{query.featureCode}
    AND d.station_id = #{query.stationId}

        AND d.station_id IN
        #{stationId}

    AND d.instrument_id = #{query.instrumentId}

        AND d.instrument_id IN
        #{instrumentId}


        AND (d.metric_code = #{query.metricCode} OR d.engineering_metric_code = #{query.metricCode})

    AND d.horizon_minutes <= #{query.maxHorizonMinutes}

        AND LOWER(COALESCE(d.quality_flag, 'normal')) = LOWER(#{query.qualityFilter})

    AND d.future_time >= #{query.startTime}
    AND d.future_time <= #{query.endTime}

ORDER BY d.future_time ASC, d.target_type ASC, d.feature_code ASC, d.step ASC
LIMIT #{limit}
